#!/usr/bin/env python3
"""
World Model: 코드의 '의도'를 학습하고 기억하는 모델
프로그램의 목적, 제약조건, 설계 원칙을 추상적으로 모델링
"""
import sys
sys.path.insert(0, '/data/data/com.termux/files/home/.projects/core/sovereign-self-evolving-factory/src')

from dataclasses import dataclass, field
from typing import List, Dict, Any, Set
import json


@dataclass
class CodeAttribute:
    """코드 속성 (의도, 제약, 목표)"""
    name: str
    value: str
    confidence: float  # 0~1
    source: str  # "user_input", "code_analysis", "test_feedback"

    def to_dict(self):
        return {
            "name": self.name,
            "value": self.value,
            "confidence": self.confidence,
            "source": self.source,
        }


@dataclass
class DesignPrinciple:
    """설계 원칙"""
    principle: str
    rationale: str
    priority: float  # 0~1 (높을수록 중요)

    def to_dict(self):
        return {
            "principle": self.principle,
            "rationale": self.rationale,
            "priority": self.priority,
        }


class WorldModel:
    """앱의 '세계'를 모델링"""

    def __init__(self, app_name: str):
        self.app_name = app_name
        self.attributes: List[CodeAttribute] = []
        self.principles: List[DesignPrinciple] = []
        self.learned_patterns: Dict[str, List[str]] = {}
        self.constraints: List[str] = []
        self.goals: List[str] = []

    def add_attribute(self, name: str, value: str, confidence: float, source: str):
        """속성 추가 (의도, 목표, 제약)"""
        attr = CodeAttribute(name, value, confidence, source)
        self.attributes.append(attr)

    def add_principle(self, principle: str, rationale: str, priority: float):
        """설계 원칙 추가"""
        p = DesignPrinciple(principle, rationale, priority)
        self.principles.append(p)

    def add_constraint(self, constraint: str):
        """제약조건 추가"""
        self.constraints.append(constraint)

    def add_goal(self, goal: str):
        """목표 추가"""
        self.goals.append(goal)

    def learn_from_code(self, code: str):
        """코드 분석으로부터 학습"""
        # 구조체 개수
        struct_count = code.count("struct ")
        if struct_count > 0:
            self.add_attribute(
                "struct_count",
                str(struct_count),
                0.9,
                "code_analysis"
            )

        # 함수 개수
        fn_count = code.count("fn ")
        if fn_count > 0:
            self.add_attribute(
                "function_count",
                str(fn_count),
                0.9,
                "code_analysis"
            )

        # 에러 처리 존재
        if "Result<" in code:
            self.add_attribute(
                "error_handling",
                "explicit",
                0.85,
                "code_analysis"
            )

        # 타입 힌트
        if "->" in code:
            self.add_attribute(
                "type_safety",
                "high",
                0.9,
                "code_analysis"
            )

    def learn_from_intent(self, intent_spec: Dict[str, Any]):
        """Intent로부터 학습"""
        # 앱 복잡도
        complexity = intent_spec.get("requirements", {}).get("complexity", "simple")
        self.add_attribute(
            "complexity",
            complexity,
            0.95,
            "user_input"
        )

        # 컴포넌트 개수
        comp_count = intent_spec.get("components_count", 0)
        self.add_attribute(
            "target_components",
            str(comp_count),
            0.9,
            "user_input"
        )

        # 기능 개수
        feat_count = intent_spec.get("features_count", 0)
        self.add_attribute(
            "target_features",
            str(feat_count),
            0.9,
            "user_input"
        )

        # 목표 추가
        description = intent_spec.get("description", "")
        if description:
            self.add_goal(description)

    def predict_next_improvement(self) -> List[Dict[str, Any]]:
        """다음 개선 영역 예측"""
        improvements = []

        # 구조체가 적으면 더 추가
        struct_attr = self._get_attribute("struct_count")
        if struct_attr and int(struct_attr.value) < 3:
            improvements.append({
                "area": "type_definition",
                "suggestion": "Add more struct definitions for better typing",
                "priority": 0.8,
            })

        # 함수가 적으면 더 추가
        fn_attr = self._get_attribute("function_count")
        if fn_attr and int(fn_attr.value) < 5:
            improvements.append({
                "area": "functionality",
                "suggestion": "Add more functions to cover all features",
                "priority": 0.7,
            })

        # 에러 처리 없으면 추가
        error_attr = self._get_attribute("error_handling")
        if not error_attr:
            improvements.append({
                "area": "error_handling",
                "suggestion": "Add explicit error handling with Result<T, E>",
                "priority": 0.9,
            })

        # 타입 힌트 없으면 추가
        type_attr = self._get_attribute("type_safety")
        if not type_attr:
            improvements.append({
                "area": "type_safety",
                "suggestion": "Add type hints to all functions",
                "priority": 0.85,
            })

        return improvements

    def _get_attribute(self, name: str) -> Any:
        """속성 검색"""
        for attr in self.attributes:
            if attr.name == name:
                return attr
        return None

    def get_design_guidelines(self) -> str:
        """설계 가이드라인 생성"""
        lines = []
        lines.append(f"Design Guidelines for {self.app_name}:")
        lines.append("")

        if self.goals:
            lines.append("Goals:")
            for goal in self.goals:
                lines.append(f"  - {goal}")
            lines.append("")

        if self.constraints:
            lines.append("Constraints:")
            for constraint in self.constraints:
                lines.append(f"  - {constraint}")
            lines.append("")

        if self.principles:
            lines.append("Design Principles:")
            sorted_principles = sorted(self.principles, key=lambda p: p.priority, reverse=True)
            for p in sorted_principles[:3]:  # 상위 3개만
                lines.append(f"  - {p.principle} ({p.priority:.0%})")
            lines.append("")

        if self.attributes:
            lines.append("Current State:")
            high_conf = [a for a in self.attributes if a.confidence >= 0.85]
            for attr in high_conf[:5]:  # 상위 5개
                lines.append(f"  - {attr.name}: {attr.value} ({attr.confidence:.0%})")

        return "\n".join(lines)

    def to_dict(self):
        return {
            "app_name": self.app_name,
            "attributes": [a.to_dict() for a in self.attributes],
            "principles": [p.to_dict() for p in self.principles],
            "constraints": self.constraints,
            "goals": self.goals,
            "next_improvements": self.predict_next_improvement(),
        }

    def to_json(self):
        return json.dumps(self.to_dict(), indent=2, ensure_ascii=False)


class CatastrophicForgettingPrevention:
    """Catastrophic Forgetting 방지"""

    def __init__(self):
        self.memory_buffer: List[Dict[str, Any]] = []
        self.knowledge_consolidation_interval = 5  # 5 세대마다

    def store_knowledge(self, generation: int, world_model: WorldModel, proof_score: float):
        """중요한 지식 저장"""
        # 높은 점수만 저장 (상위 20%)
        if proof_score >= 0.8:
            self.memory_buffer.append({
                "generation": generation,
                "knowledge": world_model.to_dict(),
                "proof_score": proof_score,
            })

    def consolidate_knowledge(self) -> Dict[str, Any]:
        """지식 통합 (일반화)"""
        if not self.memory_buffer:
            return {}

        # 상위 점수들의 속성 통합
        consolidated = {
            "common_attributes": {},
            "high_priority_principles": [],
            "stable_constraints": [],
        }

        # 공통 속성 찾기
        attr_counts: Dict[str, int] = {}
        for memory in self.memory_buffer:
            for attr in memory["knowledge"]["attributes"]:
                key = f"{attr['name']}:{attr['value']}"
                attr_counts[key] = attr_counts.get(key, 0) + 1

        # 70% 이상 반복된 속성만 보존
        threshold = len(self.memory_buffer) * 0.7
        consolidated["common_attributes"] = {
            k: v for k, v in attr_counts.items()
            if v >= threshold
        }

        # 우선순위 높은 원칙 통합
        for memory in self.memory_buffer:
            for principle in memory["knowledge"]["principles"]:
                if principle["priority"] >= 0.8:
                    consolidated["high_priority_principles"].append(principle)

        return consolidated

    def should_consolidate(self, current_generation: int) -> bool:
        """통합 필요 여부"""
        return current_generation % self.knowledge_consolidation_interval == 0


