#!/usr/bin/env python3
"""
Test Code Generator - Stage 3 단계 3

생성된 FV-Lang 모듈 → 자동 테스트 케이스 생성
HealingSurgeon.TestRunner 호환 형식

테스트 케이스 규칙:
- 엔드포인트당 3개 (정상/에러/경계)
- 엔티티당 2개 (struct 존재/필드 검증)
- 보안 함수 (JWT/validate) 확인
"""

from typing import List, Dict
from dataclasses import dataclass
from architecture_designer import (
    SystemArchitecture, MicroService, DataEntity, ServiceEndpoint
)


@dataclass
class TestCase:
    """테스트 케이스"""
    name: str              # "test_user_service_post_login"
    assertions: List[Dict]  # [{"type": "has_function", "value": "..."}, ...]
    description: str = ""  # 선택사항


class TestCodeGenerator:
    """FV-Lang 모듈 → TestCase 자동 생성"""

    def __init__(self):
        """초기화"""
        pass

    def generate_all(self, architecture: SystemArchitecture) -> List[Dict]:
        """
        전체 테스트 케이스 생성

        Returns:
            HealingSurgeon.TestRunner 호환 형식:
            [
                {
                    "name": "test_user_service_post_login",
                    "assertions": [
                        {"type": "has_function", "value": "post_auth_login"},
                        {"type": "contains", "value": "Result<"},
                    ]
                },
                ...
            ]
        """
        test_cases = []

        # [1] 서비스 엔드포인트별 테스트
        for service in architecture.services.services:
            test_cases.extend(self._generate_service_endpoint_tests(service))

        # [2] 엔티티별 테스트
        for entity in architecture.data_model.entities:
            test_cases.extend(self._generate_entity_tests(entity))

        # [3] 보안 함수 테스트
        test_cases.extend(self._generate_security_tests(architecture))

        # [4] Repository 함수 테스트
        test_cases.extend(self._generate_repository_tests(architecture))

        # [5] 캐싱 함수 테스트
        test_cases.extend(self._generate_caching_tests(architecture))

        return test_cases

    def _generate_service_endpoint_tests(self, service: MicroService) -> List[Dict]:
        """
        서비스 엔드포인트별 테스트 생성 (3가지)

        각 엔드포인트마다:
        1. 함수 존재 확인
        2. Result<T, Error> 반환 타입 확인
        3. 파라미터 검증
        """
        tests = []

        for endpoint in service.api_endpoints:
            # 엔드포인트 이름 변환: /auth/login → auth_login
            method = endpoint.method.lower()
            path = endpoint.path.strip('/').replace('/', '_')
            fn_name = f"{method}_{path}"

            # [Test 1] 함수 존재 확인
            test1 = {
                "name": f"test_{service.name}_{fn_name}_exists",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": fn_name  # "(" 없이
                    }
                ]
            }
            tests.append(test1)

            # [Test 2] Result<T, Error> 반환 타입
            test2 = {
                "name": f"test_{service.name}_{fn_name}_result_type",
                "assertions": [
                    {
                        "type": "contains",
                        "value": "Result<"
                    }
                ]
            }
            tests.append(test2)

            # [Test 3] 파라미터 존재
            if endpoint.request_schema:
                param_names = list(endpoint.request_schema.keys())
                test3 = {
                    "name": f"test_{service.name}_{fn_name}_params",
                    "assertions": [
                        {
                            "type": "contains",
                            "value": f"{param_names[0]}:"  # 첫 번째 파라미터
                        }
                    ]
                }
                tests.append(test3)

        return tests

    def _generate_entity_tests(self, entity: DataEntity) -> List[Dict]:
        """
        엔티티별 테스트 생성 (2가지)

        1. struct 정의 존재
        2. 필드 타입 검증
        """
        tests = []

        # [Test 1] struct 정의
        test1 = {
            "name": f"test_struct_{entity.name.lower()}_definition",
            "assertions": [
                {
                    "type": "contains",
                    "value": f"struct {entity.name}"
                }
            ]
        }
        tests.append(test1)

        # [Test 2] 필드 검증 (첫 번째 필드)
        if entity.fields:
            first_field = entity.fields[0]
            test2 = {
                "name": f"test_struct_{entity.name.lower()}_fields",
                "assertions": [
                    {
                        "type": "contains",
                        "value": f"{first_field.name}:"
                    }
                ]
            }
            tests.append(test2)

        return tests

    def _generate_security_tests(self, architecture: SystemArchitecture) -> List[Dict]:
        """
        보안 함수 테스트 (JWT, RBAC, Validation)

        1. verify_token 함수 (JWT)
        2. check_permission 함수 (RBAC)
        3. validate_input 함수 (입력 검증)
        """
        tests = []

        security = architecture.security_controls

        # [Test 1] JWT 인증
        if security.get("authentication", {}).get("method") == "JWT":
            test1 = {
                "name": "test_security_jwt_verification",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": "verify_token"
                    },
                    {
                        "type": "contains",
                        "value": "HS256"
                    }
                ]
            }
            tests.append(test1)

        # [Test 2] RBAC (Role-Based Access Control)
        if security.get("authorization", {}).get("type") == "RBAC":
            test2 = {
                "name": "test_security_rbac_enforcement",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": "check_permission"
                    }
                ]
            }
            tests.append(test2)

        # [Test 3] 입력 검증
        if len(architecture.data_model.entities) > 0:
            entity = architecture.data_model.entities[0]
            test3 = {
                "name": f"test_security_input_validation_{entity.name}",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": f"validate_{entity.name.lower()}"
                    }
                ]
            }
            tests.append(test3)

        return tests

    def _generate_repository_tests(self, architecture: SystemArchitecture) -> List[Dict]:
        """
        Repository 패턴 함수 테스트

        각 DB 사용 서비스마다:
        1. find_by_id 함수
        2. save 함수
        3. delete 함수
        """
        tests = []

        for service in architecture.services.services:
            if not service.database or service.database == "none":
                continue

            # 엔티티 이름을 lowercase로
            for entity in architecture.data_model.entities:
                entity_lower = entity.name.lower()

                # [Test 1] find_by_id
                test1 = {
                    "name": f"test_{service.name}_repository_find_{entity_lower}",
                    "assertions": [
                        {
                            "type": "has_function",
                            "value": f"find_{entity_lower}_by_id"
                        }
                    ]
                }
                tests.append(test1)

                # [Test 2] save
                test2 = {
                    "name": f"test_{service.name}_repository_save_{entity_lower}",
                    "assertions": [
                        {
                            "type": "has_function",
                            "value": f"save_{entity_lower}"
                        }
                    ]
                }
                tests.append(test2)

                # [Test 3] delete
                test3 = {
                    "name": f"test_{service.name}_repository_delete_{entity_lower}",
                    "assertions": [
                        {
                            "type": "has_function",
                            "value": f"delete_{entity_lower}"
                        }
                    ]
                }
                tests.append(test3)

        return tests

    def _generate_caching_tests(self, architecture: SystemArchitecture) -> List[Dict]:
        """
        캐싱 함수 테스트

        캐시 사용 엔티티마다:
        1. get_cached_* 함수
        2. set_cached_* 함수
        """
        tests = []

        for entity in architecture.data_model.entities:
            if not entity.cache_strategy or entity.cache_strategy == "none":
                continue

            entity_lower = entity.name.lower()

            # [Test 1] get_cached
            test1 = {
                "name": f"test_cache_get_{entity_lower}",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": f"get_cached_{entity_lower}"
                    }
                ]
            }
            tests.append(test1)

            # [Test 2] set_cached
            test2 = {
                "name": f"test_cache_set_{entity_lower}",
                "assertions": [
                    {
                        "type": "has_function",
                        "value": f"set_cached_{entity_lower}"
                    }
                ]
            }
            tests.append(test2)

        return tests

    def get_test_count_estimate(self, architecture: SystemArchitecture) -> Dict[str, int]:
        """
        예상 테스트 개수 계산

        Returns:
            {
                "endpoints": N,
                "entities": N,
                "security": N,
                "repository": N,
                "caching": N,
                "total": N
            }
        """
        count = {
            "endpoints": 0,
            "entities": 0,
            "security": 0,
            "repository": 0,
            "caching": 0,
        }

        # 엔드포인트: 각각 3개
        for service in architecture.services.services:
            count["endpoints"] += len(service.api_endpoints) * 3

        # 엔티티: 각각 2개
        count["entities"] = len(architecture.data_model.entities) * 2

        # 보안: JWT 1개 + RBAC 1개 + Validation 1개
        security = architecture.security_controls
        if security.get("authentication", {}).get("method") == "JWT":
            count["security"] += 1
        if security.get("authorization", {}).get("type") == "RBAC":
            count["security"] += 1
        if len(architecture.data_model.entities) > 0:
            count["security"] += 1

        # Repository: DB 서비스 * 엔티티 * 3
        db_service_count = sum(
            1 for s in architecture.services.services
            if s.database and s.database != "none"
        )
        count["repository"] = db_service_count * len(architecture.data_model.entities) * 3

        # Caching: 캐시 엔티티 * 2
        cached_entity_count = sum(
            1 for e in architecture.data_model.entities
            if e.cache_strategy and e.cache_strategy != "none"
        )
        count["caching"] = cached_entity_count * 2

        count["total"] = sum(v for k, v in count.items() if k != "total")

        return count


# ============ 데모 ============

def demo():
    """테스트 생성 데모"""
    from architecture_designer import ArchitectureDesigner

    print("\n" + "="*70)
    print("Test Code Generator - 데모")
    print("="*70)

    designer = ArchitectureDesigner()
    architecture = designer.design_todo_app()

    # 테스트 생성
    gen = TestCodeGenerator()
    test_cases = gen.generate_all(architecture)

    print(f"\n[생성된 테스트 케이스: {len(test_cases)}개]")
    print()

    for i, test in enumerate(test_cases[:5], 1):
        print(f"  {i}. {test['name']}")
        for assertion in test['assertions']:
            print(f"     - {assertion['type']}: {assertion['value']}")

    if len(test_cases) > 5:
        print(f"\n  ... 그 외 {len(test_cases) - 5}개 테스트")

    # 예상 개수 계산
    print("\n[테스트 개수 예측]")
    counts = gen.get_test_count_estimate(architecture)
    for key, count in counts.items():
        if key != "total":
            print(f"  {key:15}: {count}개")
    print(f"  {'total':15}: {counts['total']}개")

    # ============ 고규모 API 분석 ============
    print("\n" + "="*70)
    print("[고규모 API 서버]")
    print("="*70)

    architecture2 = designer.design_high_scale_api()
    test_cases2 = gen.generate_all(architecture2)

    print(f"\n[생성된 테스트 케이스: {len(test_cases2)}개]")

    counts2 = gen.get_test_count_estimate(architecture2)
    print(f"\n[테스트 개수 예측]")
    for key, count in counts2.items():
        if key != "total":
            print(f"  {key:15}: {count}개")
    print(f"  {'total':15}: {counts2['total']}개")


if __name__ == "__main__":
    demo()

    print("\n" + "="*70)
    print("✅ Test Code Generator v1.0")
    print("="*70)
    print("""
    기능:
    ✓ 엔드포인트별 테스트 (3개: 존재/타입/파라미터)
    ✓ 엔티티별 테스트 (2개: 정의/필드)
    ✓ 보안 함수 테스트 (JWT/RBAC/Validation)
    ✓ Repository 패턴 테스트 (find/save/delete)
    ✓ 캐싱 함수 테스트 (get/set)
    ✓ HealingSurgeon 호환 형식
    """)

